        jdbc.update("INSERT INTO setting_log (sheet_id, setting_key, from_date, val, made_on) VALUES (?, ?, ?, ?, "
                + "(SELECT today FROM sheet WHERE id = ?))", sheetId, key, from, value, sheetId);
